package com.ynxweb4.shop;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import java.util.concurrent.atomic.AtomicInteger;
public final class BuyerTransitionRecoveryTest {
 static final String A=BuyerJourneyTest.A,B=BuyerJourneyTest.B,path="/orders/ord_original/transition";
 static JSONObject body()throws Exception{return new JSONObject().put("Action","cancelled").put("IdempotencyKey","original-cancel-request");}
 static JSONObject value(JSONObject body)throws Exception{return new JSONObject().put("Actor",A).put("OrderID","ord_original").put("Action",body.getString("Action")).put("IdempotencyKey",body.getString("IdempotencyKey")).put("Order",BuyerJourneyTest.order().put("Status","cancelled"));}
 @Test public void canonicalDraftUsesCurrentAccountAndPreservesRetiredLegacyToken()throws Exception{
  PrivacyLifecycleTest.Memory m=new PrivacyLifecycleTest.Memory();m.put("commerce_session","retired-original-token-bytes");ProductSession session=BuyerJourneyTest.session("a".repeat(64));OfflineMutationQueue queue=new OfflineMutationQueue(m);queue.enqueueForSession(session,0,"POST",path,body());assertEquals("retired-original-token-bytes",m.get("commerce_session"));JSONObject row=new JSONArray(m.get("offline_mutations")).getJSONObject(0);assertEquals(A,row.getString("account"));assertEquals("original-cancel-request",row.getJSONObject("body").getString("IdempotencyKey"));assertEquals(1,queue.size());
 }
 @Test public void coldQueueOnlyLooksUpOriginalTypedRequestAndRetainsForeignRows()throws Exception{
  PrivacyLifecycleTest.Memory m=new PrivacyLifecycleTest.Memory();ProductSession current=BuyerJourneyTest.session("a".repeat(64));OfflineMutationQueue queue=new OfflineMutationQueue(m);queue.enqueueForSession(current,0,"POST",path,body());JSONArray rows=new JSONArray(m.get("offline_mutations"));JSONObject foreign=new JSONObject().put("id","foreign-row").put("account",B).put("method","POST").put("path",path).put("body",body());rows.put(foreign);m.put("offline_mutations",rows.toString());AtomicInteger calls=new AtomicInteger();int count=new OfflineMutationQueue(m).flush(new OfflineMutationQueue.Sender(){public ProductSession session(){return current;}public JSONObject requestForSession(String method,String actual,JSONObject input,ProductSession expected,long generation)throws Exception{assertEquals("POST",method);assertEquals(path+"-intent-lookup",actual);assertEquals(body().toString(),input.toString());calls.incrementAndGet();return value(input);}},current,0);assertEquals(1,count);assertEquals(1,calls.get());JSONArray left=new JSONArray(m.get("offline_mutations"));assertEquals(1,left.length());assertEquals(foreign.toString(),left.getJSONObject(0).toString());
 }
 @Test public void mismatchedReceiptCannotClearOriginalQueue()throws Exception{
  PrivacyLifecycleTest.Memory m=new PrivacyLifecycleTest.Memory();ProductSession current=BuyerJourneyTest.session("a".repeat(64));OfflineMutationQueue queue=new OfflineMutationQueue(m);queue.enqueueForSession(current,0,"POST",path,body());String bytes=m.get("offline_mutations");int count=queue.flush(new OfflineMutationQueue.Sender(){public ProductSession session(){return current;}public JSONObject requestForSession(String method,String actual,JSONObject input,ProductSession expected,long generation)throws Exception{return value(input).put("Actor",B);}},current,0);assertEquals(0,count);assertEquals(bytes,m.get("offline_mutations"));
 }
 @Test public void onlineUnknownOriginalRequiresExactReadbackAndCurrentGeneration()throws Exception{
  PrivacyLifecycleTest.Memory m=new PrivacyLifecycleTest.Memory();ProductSession expected=BuyerJourneyTest.session("a".repeat(64));PrivacyLifecycle privacy=new PrivacyLifecycle(m);PrivacyLifecycle.Ticket ticket=privacy.admit(A,"POST",path,body());privacy.dispatch(ticket);privacy.outcome(ticket,false);String original=m.get(PrivacyLifecycle.RECORD);OfflineMutationQueue.Sender bad=new OfflineMutationQueue.Sender(){public ProductSession session(){return expected;}public JSONObject requestForSession(String method,String actual,JSONObject input,ProductSession current,long generation)throws Exception{return value(input).put("IdempotencyKey","another-key");}};assertThrows(SecurityException.class,()->BuyerTransitionRecovery.recoverTracked(privacy,bad,expected,0));assertEquals(original,m.get(PrivacyLifecycle.RECORD));
  OfflineMutationQueue.Sender valid=new OfflineMutationQueue.Sender(){public ProductSession session(){return expected;}public JSONObject requestForSession(String method,String actual,JSONObject input,ProductSession current,long generation)throws Exception{assertEquals(path+"-intent-lookup",actual);return value(input);}};assertEquals(1,BuyerTransitionRecovery.recoverTracked(privacy,valid,expected,0));assertEquals(0,privacy.snapshot(A).getJSONObject("requests").length());
 }
 @Test public void accountOrPrivacyReplacementAfterLookupKeepsOriginalUnknown()throws Exception{
  for(boolean replacePrivacy:new boolean[]{false,true}){PrivacyLifecycleTest.Memory m=new PrivacyLifecycleTest.Memory();ProductSession expected=BuyerJourneyTest.session("a".repeat(64));ProductSession[] current={expected};PrivacyLifecycle privacy=new PrivacyLifecycle(m);PrivacyLifecycle.Ticket ticket=privacy.admit(A,"POST",path,body());privacy.dispatch(ticket);privacy.outcome(ticket,false);
   OfflineMutationQueue.Sender sender=new OfflineMutationQueue.Sender(){public ProductSession session(){return current[0];}public JSONObject requestForSession(String method,String actual,JSONObject input,ProductSession original,long generation)throws Exception{if(replacePrivacy)privacy.begin(A);else current[0]=BuyerJourneyTest.session("b".repeat(64));return value(input);}};assertThrows(SecurityException.class,()->BuyerTransitionRecovery.recoverTracked(privacy,sender,expected,0));assertTrue(privacy.snapshot(A).getJSONObject("requests").has(ticket.id));
  }
 }
 @Test public void malformedSuccessRemainsUnknownBeforeLedgerAcknowledgement()throws Exception{
  PrivacyLifecycleTest.Memory m=new PrivacyLifecycleTest.Memory();ProductSession expected=BuyerJourneyTest.session("a".repeat(64));PrivacyLifecycle privacy=new PrivacyLifecycle(m);PrivacyLifecycle.Ticket ticket=privacy.admit(A,"POST",path,body());assertThrows(SecurityException.class,()->ApiClient.executeTracked(privacy,ticket,()->true,()->ApiClient.validateTransitionResponse(new ApiClient.Response(200,BuyerJourneyTest.order().put("Status","cancelled").put("ID","another")),"POST",path,expected,body())));assertEquals("UNKNOWN",privacy.snapshot(A).getJSONObject("requests").getJSONObject(ticket.id).getString("status"));assertEquals(NativeProductState.canonical(NativeProductState.buyerScopes()),NativeProductState.canonical(NativeBusinessPolicy.scopes("POST","/api"+path+"-intent-lookup")));
 }
}
